"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1245],{31245:e=>{e.exports=JSON.parse('{"slug":"sankcii-ssha-platezhnaya-set-a7","locale":"ru","title":"США предложили запретить банкам переводы через сотни компаний платёжной сети A7","description":"Минфин США 1 октября признал сеть A7 преступной организацией и предложил запретить банкам переводы через её субагентов. Как это влияет на импорт.","blocks":[{"id":"b001","kind":"paragraph","text":"Министерство финансов США 1 октября 2026 года признало российскую платёжную сеть A7 \xabзначительной транснациональной преступной организацией\xbb. Одновременно его подразделение по финансовым преступлениям FinCEN предложило запретить американским банкам любые переводы с участием \xabсубагентов\xbb A7. Так называют подставные компании за рубежом, через которые сеть проводит платежи российских клиентов."},{"id":"b002","kind":"paragraph","text":"Платёжную сеть A7 запустили в 2024 году молдавский бизнесмен Илан Шор и Промсвязьбанк. Сеть берёт за перевод 0,3% и выпускает рублёвый стейблкоин A7A5, цифровую монету, привязанную к рублю. Российская часть A7 и её стейблкоин под санкциями США с августа 2025 года, но платежи шли через иностранные фирмы. Американские власти связывают сеть и с Ираном: по их версии, ею пользовались Центральный банк Ирана и Корпус стражей исламской революции. Сам запрет FinCEN опирается на закон о борьбе с отмыванием российских денег."},{"id":"b003","kind":"paragraph","text":"Масштаб сети A7 большой. У неё сотни субагентов в ОАЭ, Гонконге, Турции, Киргизии и других странах, со счетами примерно в 435 банках в 83 странах. С января 2025 по июнь 2026 года они провели больше $17 млрд долларовых платежей. Это лишь часть оборота: к январю 2026 года сеть заявляла о 7,5 трлн рублей переводов за всё время. Сам Промсвязьбанк оценивал, что в первом полугодии 2025 года через A7 шло почти 12% внешней торговли России. FinCEN называет близкую цифру: почти 13% за весь 2025 год."},{"id":"b004","kind":"paragraph","text":"Почему США могут остановить чужие платежи. Перевод в долларах между банками разных стран почти всегда проходит через счёт в американском банке. Это похоже на посылку, которая едет через сортировочный центр: если центр её не примет, она не дойдёт, даже если отправитель и получатель живут в других странах. Такой счёт называют корреспондентским. Запрет отрезает субагентов A7 от этого центра. Но удар может прийтись не только по долларам: банки в других странах, где у субагентов счета, рискуют сами попасть под санкции и проще закроют такие счета в любой валюте. Полный список фирм банкам разошлют закрыто и будут пополнять."},{"id":"b005","kind":"paragraph","text":"Напрямую кошелька обычного человека санкции против A7 не касаются: сеть работает с компаниями. Канал косвенный, через цены импорта. Каждая новая преграда в расчётах делает платёж за границу дольше и дороже, а эти издержки компании закладывают в цену товара. Насколько вырастут цены, оценить нельзя. A7 уже попадала под санкции США в 2025 году и продолжала работать через новые фирмы."},{"id":"b006","kind":"paragraph","text":"Правило FinCEN пока проект: после публикации на комментарии дают 30 дней. Минфин США рассчитывает, что за ним пойдут другие страны и банки, но неизвестно, сделают ли они это. Для покупателя импортной техники и запчастей новость не повод скупать заранее: эффект растянется на месяцы и смешается с движением курса рубля. Но и считать, что удары по платёжным схемам проходят мимо, тоже не стоит, потому что дорогие расчёты в итоге оказываются в цене товара."},{"id":"b007","kind":"heading","text":"Что такое платёжная сеть A7?"},{"id":"b008","kind":"paragraph","text":"Это система международных переводов, которую в 2024 году запустили Илан Шор и Промсвязьбанк. Она проводит платежи российских компаний через подставные фирмы за рубежом, берёт комиссию 0,3% и выпускает рублёвый стейблкоин A7A5."},{"id":"b009","kind":"heading","text":"Какие санкции ввели США против A7 в октябре 2026 года?"},{"id":"b010","kind":"paragraph","text":"1 октября 2026 года Минфин США признал A7 транснациональной преступной организацией. FinCEN предложил запретить американским банкам переводы через сотни её субагентов, у которых счета примерно в 435 банках в 83 странах."},{"id":"b011","kind":"heading","text":"Подорожает ли импорт из-за санкций против A7?"},{"id":"b012","kind":"paragraph","text":"Возможно, но насколько, неизвестно. Через A7 шло почти 12–13% внешней торговли России, и каждая новая преграда делает расчёты дольше и дороже. Эти издержки компании закладывают в цену товаров."}],"sources":[{"label":"США ввели санкции против платежной системы A7","url":"https://www.kommersant.ru/doc/8991793"},{"label":"США готовят запрет на платежи через сотни зарубежных компаний A7","url":"https://thebell.io/ssha-gotovyat-zapret-na-platezhi-cherez-sotni-zarubezhnykh-kompaniy-a7-po-otsenke-psb-cherez-etu-set-shlo-pochti-12-vneshney-torgovli-rossii"},{"label":"Proposal of Special Measure Regarding A7 Network Sub-Agents","url":"https://www.fincen.gov/system/files/2026-10/9714-A7-NETWORK-NPRM.pdf"}],"sourceBodySha256":"e928692ceb98a757973abed5533e72f30df7536893758054b08fc807c779360a"}')}}]);